                || !owner.HasExited
                || !ReferenceEquals(Interlocked.CompareExchange(ref slot.Owner, current, owner), owner))
            {
                return false;
            }
        }

        return ReferenceEquals(Interlocked.CompareExchange(ref slot.Element, returned, token), token);
    }

